"""Curated GIS raster discovery; separate from vector GIS operations."""
import json
from importlib.resources import files


def catalogue():
    result = {'application':{'label':'GDAL','purpose':'Extract georeferenced raster pixel windows and resize grids with independently checked nearest-neighbour samples.','keywords':['GDAL','GeoTIFF','raster window','nearest neighbour']},'searchCases':json.loads(files(__package__).joinpath('search-cases.json').read_text()),'requirements':['Isolated GDAL3.13.3 Python interpreter on POSIX.','Single-band uncompressed north-up PixelIsArea GeoTIFF with explicit CRS, units and nodata.'],'references':['docs/gdal.md','src/schemaxis/adaptors/gdal/readiness.json'],'operations':{'window':{'purpose':'Crop a GeoTIFF raster by integer pixel window and resize its grid with nearest-neighbour centre sampling while retaining CRS, units, nodata and window extent.','keywords':['raster window','GeoTIFF','crop elevation','nearest neighbour','resample raster','GDAL Translate','pixel window','GIS raster','DEM','digital elevation model','raster'],'semantics':['Pixel offsets count columns from left and rows from top; coordinates retain north-up negative y spacing.','EPSG4326 uses longitude/latitude degrees;3857 uses metres. No reprojection, averaging, bilinear interpolation or geodesic area.','Independent TIFF parser compares all pixels and affine metadata with source oracle; fresh GDAL opening adds readback.'],'examples':[{'reference':'examples/schemaxis/gdal-window.json','purpose':'Extract a nodata-aware elevation window.'},{'reference':'examples/schemaxis/gdal-window-variant.json','purpose':'Resize the window with a non-integer sampling ratio.'}]}}}
    result['application']['purpose']='Extract georeferenced raster pixel windows, resize grids with independently checked nearest-neighbour samples, and summarise named pixel-aligned rectangular zones into typed tables.'
    result['application']['keywords']+=['zonal statistics','zonal stats','raster zones']
    result['requirements'].append('zonalSummary uses the released GDAL 3.13.3 raster zonal-stats algorithm on authored pixel rectangles; no polygons or reprojection.')
    result['operations']['zonalSummary']={'purpose':'Summarise declared pixel-aligned rectangular zones of a GeoTIFF raster grid: valid and missing counts, coverage, minimum, maximum, sum and mean per named zone, published as a typed CSV for Calc and a JSON summary.','keywords':['zonal statistics','zonal stats','raster zones','zone summary','rectangular zones','region statistics','mean per zone','average per zone','pixel rectangle','GDAL zonal-stats','nodata coverage','typed CSV','raster','GeoTIFF'],'semantics':['Zones are authored as zero-based x, y, width and height in the captured raster pixel grid; overlap is allowed and each zone is an independent summary.','missing exclude counts exact nodata pixels as missing; refuse fails. A zone with no valid pixel has null statistics. sum is a sum of band values, not an area integral, and EPSG:4326 pixels are angular.','An independent stdlib oracle visits every included pixel and regenerates the zone geometry; native zonal-stats output and a fresh OGR reopening must agree exactly or within a stated roundoff bound.'],'examples':[{'reference':'examples/schemaxis/gdal-zonal.json','purpose':'Four elevation zones with overlap, nodata and an all-missing zone.'},{'reference':'examples/schemaxis/gdal-zonal-temperature.json','purpose':'Float32 Kelvin zones on an EPSG:4326 grid with the refuse policy.'}]}
    return result
